package com.bank.scheduler;

import java.util.logging.*;

public class SchedulerDemo {
    private static final Logger log = Logger.getLogger("Sched");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        JobStore store = new JobStore();
        Scheduler scheduler = new Scheduler(store);
        WorkerPool workers = new WorkerPool(store, 3); // max 2 per tenant

        long now = System.currentTimeMillis();
        // Daily interest job (bank tenant), due now
        store.schedule(new Job("JOB-INTEREST", "BANK", "calc-interest", now));
        // Several report jobs from a flooding corporate tenant
        for (int i = 1; i <= 4; i++)
            store.schedule(new Job("JOB-REPORT-" + i, "CORP", "report", now));
        // Rajesh's statement job
        store.schedule(new Job("JOB-STMT-RAJESH", "RETAIL", "statement", now));

        // First dispatch round
        scheduler.dispatchDue(workers, now);

        // Simulate the interest worker crashing (lease expires), then recovery
        log.info("Simulating interest worker crash (lease expires)...");
        store.expireLease("JOB-INTEREST");
        scheduler.dispatchDue(workers, now + 1);  // re-dispatch
        // Dedup prevents double interest effect
    }
}

