package com.bank.scheduler;

public class Job {
    public enum State { PENDING, RUNNING, DONE, FAILED, DEAD }
    private final String id;
    private final String tenant;
    private final String payload;
    private final long dueAt;
    private State state = State.PENDING;
    private String leaseOwner;
    private long leaseExpiry;
    private int attempts = 0;

    public Job(String id, String tenant, String payload, long dueAt) {
        this.id = id; this.tenant = tenant; this.payload = payload; this.dueAt = dueAt;
    }
    public String id() { return id; }
    public String tenant() { return tenant; }
    public String payload() { return payload; }
    public long dueAt() { return dueAt; }
    public State state() { return state; }
    public void setState(State s) { this.state = s; }
    public void setLeaseOwner(String w) { this.leaseOwner = w; }
    public void setLeaseExpiry(long t) { this.leaseExpiry = t; }
    public long leaseExpiry() { return leaseExpiry; }
    public int attempts() { return attempts; }
    public void incrementAttempts() { attempts++; }
}
