package com.bank.scheduler;

import java.util.*;
import java.util.stream.*;

public class JobStore {
    private final Map<String, Job> jobs = new LinkedHashMap<>();
    public void schedule(Job j) { jobs.put(j.id(), j); }
    public Job get(String id) { return jobs.get(id); }

    public List<Job> dueJobs(long now, int limit) {
        return jobs.values().stream()
            .filter(j -> j.state() == Job.State.PENDING && j.dueAt() <= now)
            .sorted(Comparator.comparingLong(Job::dueAt))
            .limit(limit).collect(Collectors.toList());
    }
    // simulate a crashed worker: lease expires, job returns to PENDING
    public void expireLease(String id) {
        Job j = jobs.get(id);
        if (j != null && j.state() == Job.State.RUNNING) j.setState(Job.State.PENDING);
    }
}
